def followup_view(inputs, prior):
    packet=inputs.get('twentythird_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('twentythird period packet changed')
    if prior is None or prior['counts']['after']!=134 or packet['prior_digest']!=digest(prior):raise ValueError('twentythird period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('twentythird period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=32 or len(packet['sources'])!=32 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('twentythird period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('twentythird period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('twentythird period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('twentythird period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('twentythird period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('twentythird period page changed')
    for row in FINANCIAL:
        if D(row['nine_month_yuan'])-D(row['h1_yuan'])!=D(row['quarter_yuan']):raise ValueError('quarter arithmetic changed')
        if row['reported_quarter_yuan'] is not None and D(row['quarter_yuan'])!=D(row['reported_quarter_yuan']):raise ValueError('quarter direct mismatch')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace(' ','').replace('\n','')
            if any(row[k]not in text for k in keys):raise ValueError('financial source binding changed')
    for r in VISUAL:
        source=sources[r['announcement_id']]
        if source['sha256']!=r['source_sha256'] or source['page_hashes'][r['page']-1]!=r['page_text_sha256'] or not r['verified']:raise ValueError('visual binding changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('twentythird period windows changed')
