    result.update(chains=CHAINS,financial_bridge=FINANCIAL,phase_comparisons=[],event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ["raw_item","selected_pages","page_hashes"]}for s in sources.values()])
    return result
